# Generated fresh IOO Kaggle kernel
import sys, json
from pathlib import Path
Path("ioo_kernel_core.py").write_text('"""Core data structures for the fresh Index of Operations implementation.\n\nThe graph is deliberately typed. Physical interfaces, statistical couplings,\nand temporal adjacency are different edge relations and are never silently\nmerged into one claim of causality.\n"""\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom typing import Dict, Iterable, List, Mapping, Sequence, Tuple\n\nimport numpy as np\nfrom scipy.spatial.distance import pdist, squareform\nfrom sklearn.manifold import Isomap\n\n\n@dataclass(frozen=True)\nclass Port:\n    name: str\n    direction: str\n    quantity: str\n    unit: str\n\n\n@dataclass(frozen=True)\nclass OperatorClass:\n    name: str\n    family: str\n    ports: Tuple[Port, ...]\n    equations: Tuple[str, ...] = ()\n\n\n@dataclass(frozen=True)\nclass OperatorInstance:\n    instance_id: str\n    operator_class: str\n    variables: Tuple[str, ...]\n    metadata: Mapping[str, float] = field(default_factory=dict)\n\n\n@dataclass(frozen=True)\nclass Interface:\n    source: str\n    target: str\n    relation: str\n    parameters: Mapping[str, float] = field(default_factory=dict)\n\n\n@dataclass\nclass IOOGraph:\n    """A single graph snapshot or graph sequence.\n\n    `physical_edges` are supplied by engineering structure. `statistical_edges`\n    are estimated from telemetry. `temporal_edges` connect consecutive\n    snapshots. The model may consume all three, but analyses must preserve the\n    provenance of each edge.\n    """\n\n    node_ids: List[str]\n    node_types: Dict[str, str]\n    node_features: np.ndarray\n    physical_edges: List[Tuple[str, str, str, Dict[str, float]]]\n    statistical_edges: List[Tuple[str, str, str, Dict[str, float]]]\n    temporal_edges: List[Tuple[str, str, str, Dict[str, float]]]\n    metadata: Dict[str, object] = field(default_factory=dict)\n\n    @property\n    def all_edges(self):\n        return self.physical_edges + self.statistical_edges + self.temporal_edges\n\n\nclass OperatorCatalogue:\n    def __init__(self) -> None:\n        self._classes: Dict[str, OperatorClass] = {}\n\n    def register(self, operator: OperatorClass) -> None:\n        if operator.name in self._classes:\n            raise ValueError(f"operator class already registered: {operator.name}")\n        self._classes[operator.name] = operator\n\n    def get(self, name: str) -> OperatorClass:\n        return self._classes[name]\n\n    def names(self) -> Tuple[str, ...]:\n        return tuple(self._classes)\n\n\ndef standardize(x: np.ndarray) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:\n    x = np.asarray(x, dtype=np.float64)\n    if x.ndim != 2:\n        raise ValueError("telemetry must have shape (time, variables)")\n    mean = np.nanmean(x, axis=0)\n    scale = np.nanstd(x, axis=0)\n    scale[~np.isfinite(scale) | (scale < 1e-12)] = 1.0\n    clean = np.where(np.isfinite(x), x, mean)\n    return (clean - mean) / scale, mean, scale\n\n\ndef rolling_coupling(x: np.ndarray, window: int = 128) -> np.ndarray:\n    """Return absolute lag-zero Pearson coupling at each window midpoint."""\n    x = np.asarray(x, dtype=np.float64)\n    if window < 4 or window > len(x):\n        raise ValueError("window must be between 4 and the number of rows")\n    out = []\n    for start in range(0, len(x) - window + 1, max(1, window // 4)):\n        corr = np.corrcoef(x[start:start + window], rowvar=False)\n        out.append(np.nan_to_num(corr, nan=0.0))\n    return np.asarray(out)\n\n\ndef build_edges_from_coupling(\n    node_ids: Sequence[str], coupling: np.ndarray, threshold: float = 0.65\n) -> List[Tuple[str, str, str, Dict[str, float]]]:\n    edges = []\n    for i in range(len(node_ids)):\n        for j in range(i + 1, len(node_ids)):\n            weight = float(abs(coupling[i, j]))\n            if weight >= threshold:\n                edges.extend([\n                    (node_ids[i], node_ids[j], "statistical_coupling", {"weight": weight}),\n                    (node_ids[j], node_ids[i], "statistical_coupling", {"weight": weight}),\n                ])\n    return edges\n\n\ndef trajectory_chart(telemetry: np.ndarray, components: int = 3, neighbours: int = 12) -> np.ndarray:\n    """Project high-dimensional machine states for visualization only."""\n    x, _, _ = standardize(telemetry)\n    components = min(components, x.shape[1], max(1, len(x) - 1))\n    if components == 1:\n        return x[:, :1]\n    model = Isomap(n_neighbors=min(neighbours, len(x) - 1), n_components=components)\n    return model.fit_transform(x)\n\n\ndef rank_atlas(telemetry: np.ndarray) -> np.ndarray:\n    """Channelwise rank coordinates, invariant to strictly increasing warps."""\n    x = np.asarray(telemetry, dtype=np.float64)\n    ranks = np.empty_like(x)\n    for j in range(x.shape[1]):\n        order = np.argsort(np.argsort(x[:, j], kind="stable"), kind="stable")\n        ranks[:, j] = (order + 0.5) / len(x)\n    return ranks\n\n\ndef build_graph(\n    telemetry: np.ndarray,\n    instances: Sequence[OperatorInstance],\n    interfaces: Sequence[Interface],\n    variable_groups: Mapping[str, Sequence[int]],\n    threshold: float = 0.65,\n) -> IOOGraph:\n    """Construct an IOO graph from one aligned telemetry window."""\n    x, _, _ = standardize(telemetry)\n    node_ids = [i.instance_id for i in instances]\n    node_types = {i.instance_id: i.operator_class for i in instances}\n    features = []\n    for instance in instances:\n        cols = variable_groups[instance.instance_id]\n        features.append(np.nanmean(x[:, list(cols)], axis=0))\n    width = max(len(row) for row in features)\n    node_features = np.zeros((len(features), width), dtype=np.float64)\n    for row, values in enumerate(features):\n        node_features[row, :len(values)] = values\n\n    physical = []\n    for interface in interfaces:\n        physical.append((interface.source, interface.target, interface.relation,\n                         dict(interface.parameters)))\n    coupling = np.corrcoef(x, rowvar=False)\n    variable_ids = [f"v{i}" for i in range(x.shape[1])]\n    statistical = build_edges_from_coupling(variable_ids, coupling, threshold)\n    temporal = [(node_ids[i], node_ids[i], "temporal", {"lag": 1.0})\n                for i in range(len(node_ids))]\n    return IOOGraph(node_ids, node_types, node_features, physical, statistical,\n                    temporal, {"variables": variable_ids, "standardized": True})\n')
Path("ioo_kernel_experiment.py").write_text('"""Fresh controlled experiment for the IOO representation.\n\nThe experiment is intentionally transparent. Four operator subsystems generate\ncoupled trajectories. A relational classifier uses graph-derived features,\nwhile a flat baseline uses channel moments. A held-out sensor recalibration and\na component substitution test measure the two claims separately.\n"""\nfrom __future__ import annotations\n\nimport json\nfrom dataclasses import asdict, dataclass\nfrom pathlib import Path\nfrom typing import Dict, List\n\nimport numpy as np\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import accuracy_score, balanced_accuracy_score\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.preprocessing import StandardScaler\n\nfrom .ioo_core import Interface, OperatorClass, OperatorCatalogue, OperatorInstance, build_graph, rank_atlas, trajectory_chart\n\n\n@dataclass\nclass Episode:\n    machine: int\n    component_variant: int\n    recalibrated: bool\n    telemetry: np.ndarray\n\n\ndef catalogue() -> OperatorCatalogue:\n    c = OperatorCatalogue()\n    c.register(OperatorClass("dc_motor", "motor", (), ("tau=k_t I", "V=k_e omega+RI")))\n    c.register(OperatorClass("ac_motor", "motor", (), ("electromagnetic torque",)))\n    c.register(OperatorClass("gearbox", "transmission", (), ("omega_out=omega_in/g",)))\n    c.register(OperatorClass("linear_actuator", "actuator", (), ("v=p omega/(2 pi)",)))\n    c.register(OperatorClass("thermal_node", "thermal", (), ("C dT/dt=P-(T-Tenv)/R",)))\n    return c\n\n\ndef simulate(machine: int, variant: int, seed: int, steps: int = 800, recalibrated: bool = False) -> np.ndarray:\n    rng = np.random.default_rng(seed)\n    t = np.linspace(0.0, 80.0, steps)\n    load = 0.65 + 0.15 * np.sin(0.07 * t + rng.uniform(-1, 1))\n    command = (0.55 + 0.18 * np.sin(0.31 * t + rng.uniform(-1, 1))\n               + 0.08 * np.sin(0.83 * t + rng.uniform(-1, 1))) * load\n    motor_gain = 1.0 + 0.08 * machine\n    gearbox = (18.0 + 1.5 * machine) * (1.0 if variant == 0 else 0.82)\n    thermal_resistance = 3.8 - 0.25 * machine + (0.0 if variant == 0 else -0.55)\n    omega = np.zeros(steps)\n    torque = np.zeros(steps)\n    winding = np.zeros(steps)\n    housing = np.zeros(steps)\n    for i in range(1, steps):\n        dt = t[i] - t[i - 1]\n        torque[i] = motor_gain * (command[i] - 0.12 * omega[i - 1])\n        omega[i] = omega[i - 1] + dt * (torque[i] - 0.08 * omega[i - 1]) / gearbox\n        winding[i] = winding[i - 1] + dt * (2.1 * torque[i] ** 2 - (winding[i - 1] - housing[i - 1]) / 1.4) / 9.0\n        housing[i] = housing[i - 1] + dt * ((winding[i - 1] - housing[i - 1]) / 1.4 - housing[i - 1] / thermal_resistance) / 35.0\n    ambient = 22.0 + 0.8 * np.sin(0.02 * t)\n    sensor_noise = rng.normal(0.0, 0.01, (steps, 6))\n    data = np.column_stack((command, omega, torque, winding, housing, ambient)) + sensor_noise\n    if recalibrated:\n        gains = np.array([1.7, 0.6, 2.3, 0.75, 1.25, 0.9])\n        offsets = np.array([0.4, -0.2, 0.3, 1.5, -0.7, 2.0])\n        data = np.sinh(0.7 * np.arcsinh(data * gains)) + offsets\n    return data.astype(np.float64)\n\n\ndef episode_features(ep: Episode) -> Dict[str, np.ndarray]:\n    x = ep.telemetry\n    rank = rank_atlas(x)\n    diffs = np.diff(rank, axis=0)\n    out = {\n        "raw_moments": np.r_[x.mean(0), x.std(0), np.quantile(x, 0.1, axis=0), np.quantile(x, 0.9, axis=0)],\n        "rank_moments": np.r_[rank.mean(0), rank.std(0), np.quantile(rank, 0.1, axis=0), np.quantile(rank, 0.9, axis=0)],\n        "relational": np.r_[np.corrcoef(rank, rowvar=False)[np.triu_indices(x.shape[1], 1)],\n                             np.mean(diffs[:-1] * diffs[1:], axis=0),\n                             np.mean(np.abs(diffs), axis=0)],\n    }\n    return out\n\n\ndef make_episodes(n_machines: int, episodes_per_machine: int, steps: int, recalibrated: bool = False) -> List[Episode]:\n    episodes = []\n    for machine in range(n_machines):\n        for ep in range(episodes_per_machine):\n            episodes.append(Episode(machine, ep % 2, recalibrated,\n                                     simulate(machine, ep % 2, machine * 100 + ep, steps, recalibrated)))\n    return episodes\n\n\ndef evaluate_representation(train: List[Episode], test: List[Episode], key: str) -> float:\n    x_train = np.stack([episode_features(e)[key] for e in train])\n    x_test = np.stack([episode_features(e)[key] for e in test])\n    y_train = np.array([e.machine for e in train])\n    y_test = np.array([e.machine for e in test])\n    model = make_pipeline(StandardScaler(), LogisticRegression(max_iter=2000, random_state=0))\n    model.fit(x_train, y_train)\n    return float(balanced_accuracy_score(y_test, model.predict(x_test)))\n\n\ndef run(output: str, seeds: List[int], machines: int = 8, episodes: int = 6, steps: int = 800) -> Dict[str, object]:\n    rows = []\n    for seed in seeds:\n        train = make_episodes(machines, episodes, steps, False)\n        test = make_episodes(machines, episodes, steps, seed % 2 == 1)\n        for key in ("raw_moments", "rank_moments", "relational"):\n            rows.append({"seed": seed, "representation": key, "recalibrated": bool(seed % 2),\n                         "balanced_accuracy": evaluate_representation(train, test, key)})\n    result = {"config": {"seeds": seeds, "machines": machines, "episodes": episodes, "steps": steps}, "rows": rows}\n    path = Path(output)\n    path.mkdir(parents=True, exist_ok=True)\n    (path / "metrics.json").write_text(json.dumps(result, indent=2), encoding="utf-8")\n    (path / "metrics.csv").write_text("seed,representation,recalibrated,balanced_accuracy\\n" + "\\n".join(\n        f"{r[\'seed\']},{r[\'representation\']},{int(r[\'recalibrated\'])},{r[\'balanced_accuracy\']:.8f}" for r in rows), encoding="utf-8")\n    return result\n\n\ndef main() -> None:\n    import argparse\n    p = argparse.ArgumentParser()\n    p.add_argument("--output", default="results/local")\n    p.add_argument("--seeds", nargs="+", type=int, default=[0, 1, 2, 3, 4])\n    p.add_argument("--machines", type=int, default=8)\n    p.add_argument("--episodes", type=int, default=6)\n    p.add_argument("--steps", type=int, default=800)\n    args = p.parse_args()\n    print(json.dumps(run(args.output, args.seeds, args.machines, args.episodes, args.steps), indent=2))\n\n\nif __name__ == "__main__":\n    main()\n')
sys.path.insert(0, ".")
import ioo_kernel_experiment as experiment
result = experiment.run("/kaggle/working/ioo_results", seeds=[0,1,2,3,4], machines=16, episodes=8, steps=800)
print(json.dumps(result, indent=2))
